import fs from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import { createServer, request } from 'node:http';
import { once } from 'node:events';
const source=fs.readFileSync('karta/src/api/server.ts','utf8');
const start=source.indexOf('async function readBody(');
const end=source.indexOf('\nfunction readActive(',start);
const bodySource=stripTypeScriptTypes(source.slice(start,end),{mode:'transform'});
const readBody=new Function(bodySource+'\nreturn readBody;')();
const observed=[];
const server=createServer(async(req,res)=>{
 try { await readBody(req);res.end('ok'); }
 catch(error) { observed.push({stage:'reader-error',status:error.status,destroyed:req.destroyed,responseDestroyed:res.destroyed});res.writeHead(error.status??500,{'Content-Type':'application/json'});res.end('{}'); }
});
server.listen(0,'127.0.0.1');await once(server,'listening');
const port=server.address().port;
await new Promise(resolve=>{
 const req=request({host:'127.0.0.1',port,method:'POST',path:'/iao/requests',headers:{'content-type':'application/json'}},res=>{
  observed.push({stage:'client-response',status:res.statusCode});res.resume();res.on('end',resolve);
 });
 req.on('error',err=>{observed.push({stage:'client-error',code:err.code});resolve();});
 req.write('a'.repeat(32768));
 setTimeout(()=>req.write('a'.repeat(32768)),10);
 setTimeout(()=>req.write('a'.repeat(1024)),20);
 setTimeout(()=>req.end('tail'),70);
});
console.log(JSON.stringify({scope:'Exact readBody function extracted from current source, real chunked HTTP client, isolated loopback server',observed}));
await new Promise(resolve=>server.close(resolve));
